      ui.btnResetPrefs.addEventListener("click", resetPrefs);
      ui.btnResetVisuals.addEventListener("click", () => {
        resetVisualizers("visuals");
        visualizerEditStatusToast("Visuals reset.");
      });
      state.canvas.addEventListener("dragover", (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = "copy";
      });
      state.canvas.addEventListener("drop", async (e) => {
        e.preventDefault();
        if (!isFileWorkflowMode(state.source)) {
          toastFileModeOnlyAction();
          return;
        }
        if (isFinalizingFileTransportLocked()) {
          toastFinalizingTransportLock();
          return;
        }
        const files = Array.from(e.dataTransfer.files).filter((f) => f.type.startsWith("audio/"));
        if (!files.length) return;
        for (const file of files) {
          const wasEmpty = Queue.length === 0;
          const idx = Queue.add(file);
          if (wasEmpty) {
            Queue.setCursor(idx);
            await loadAndPlay(file);
          }
        }
        refreshQueuePanel();
      });
      window.addEventListener("dragover", (e) => {
        if (e.dataTransfer && Array.from(e.dataTransfer.types || []).includes("Files")) e.preventDefault();
      });
      window.addEventListener("drop", (e) => {
        if (e.dataTransfer && Array.from(e.dataTransfer.types || []).includes("Files")) e.preventDefault();
      });
      function hasFocusedInteractiveTarget(event) {
        const target = event.target;
        if (!(target instanceof Element)) return false;
        if (target.closest('input, select, textarea, button, summary, [contenteditable="true"], [role="button"]')) return true;
        return false;
      }
      window.addEventListener("keydown", (e) => {
        if (e.altKey || e.ctrlKey || e.metaKey) return;
        if (hasFocusedInteractiveTarget(e)) return;
        if (e.code === "KeyH") {
          workspace.togglePanels();
          return;
        }
        if (e.code === "Space") {
          e.preventDefault();
          state.time.simPaused = !state.time.simPaused;
          return;
        }
        if (e.code === "KeyR") {
          resetVisualizers("visuals");
          return;
        }
        if (e.code === "KeyN") {
          if (!isFileWorkflowMode(state.source)) return;
          if (isFinalizingFileTransportLocked()) {
            toastFinalizingTransportLock();
            return;
          }
          const file = pickManualNextFile();
          if (file) loadAndPlay(file);
          return;
        }
        if (e.code === "KeyP") {
          if (!isFileWorkflowMode(state.source)) return;
          if (isFinalizingFileTransportLocked()) {
            toastFinalizingTransportLock();
            return;
          }
          const file = pickManualPrevFile();
          if (file) loadAndPlay(file);
          return;
        }
        if (e.code === "ArrowRight" || e.code === "ArrowLeft") {
          if (!isFileWorkflowMode(state.source)) return;
          e.preventDefault();
          const el = AudioEngine.getMediaEl();
          if (el && Number.isFinite(el.duration)) {
            const step = e.shiftKey ? 30 : 5;
            const delta = e.code === "ArrowRight" ? step : -step;
            el.currentTime = clamp(el.currentTime + delta, 0, el.duration);
          }
        }
      }, { passive: false });
      window.addEventListener("hashchange", () => {
        const ok = UrlPreset.applyFromLocationHash();
        if (ok) {
          applyPrefs(null, { rebuildBandsOnDefinitionChange: true });
          initOrbs();
          resetVisualizers("visuals");
          sceneStatusToast("Preset applied from URL.", 4e3);
        }
      });
    }
    return {
      setCssVarsFromConfig,
      wireControls,
      refreshAllUiText,
      refreshRecordingUi,
      getRecordingUiModel,
      dispatchSourceSwitchAction,
      showRecordPanel: workspace.showRecordPanel,
      hideRecordPanel: workspace.hideRecordPanel,
      dispatchRecordingAction,
      applyPrefs,
      resetTrackVisualState
    };
  })();

  // src/js/main.js
  var analysisFrame = createAnalysisFrame();
  var visualizerFrameContext = {
    dtSec: 0,
    nowSec: 0,
    simPaused: false,
    analysisFrame
  };
  function onAnimationFrame(tsMs) {
    requestAnimationFrame(onAnimationFrame);
    resizeCanvasToDisplaySize();
    if (state.time.lastTimestampMs === null) {
      state.time.lastTimestampMs = tsMs;
      return;
    }
    const dtSecRaw = (tsMs - state.time.lastTimestampMs) / 1e3;
    state.time.lastTimestampMs = tsMs;
    const dtSec = clamp(dtSecRaw, 0, runtime.settings.timing.maxDeltaTimeSec);
    const nowSec = performance.now() / 1e3;
    updateAnalysisFrame(analysisFrame, AudioEngine.sample(), state.bands);
    visualizerFrameContext.dtSec = dtSec;
    visualizerFrameContext.nowSec = nowSec;
    visualizerFrameContext.simPaused = state.time.simPaused;
    VisualizerRuntime.update(visualizerFrameContext);
    VisualizerRuntime.render(Renderer, visualizerFrameContext);
    UI.refreshAllUiText(analysisFrame);
    Scrubber.draw();
  }
  function main() {
    UI.setCssVarsFromConfig();
    state.canvas = document.getElementById("c");
    state.ctx = state.canvas.getContext("2d", { alpha: false });
    resolveSettings();
    UrlPreset.applyFromLocationHash();
    resolveSettings();
    InputSourceManager.init({
      onExternalLiveInputReset: UI.resetTrackVisualState
    });
    BandBankController.syncFromSettings();
    BandBankController.rebuildNow();
    initOrbs();
    RecorderEngine.init({
      config: CONFIG.recording,
      stateRef: state.recording,
      // Renderer owns the canonical display canvas. Recording reads it through
      // a tap descriptor only; it does not create an alternate render path.
      getRenderTap: Renderer.getRecorderTap,
      // Delegate to AudioEngine's canonical recorder-audio interface.
      // This returns { isLoaded, isPlaying, filename, ensureStream(), releaseStream() }.
      // ensureStream() yields the current recordable source audio without turning on
      // local monitoring for live inputs.
      getAudioTap: () => AudioEngine.getRecorderTap()
    });
    UI.wireControls();
    UI.applyPrefs(null);
    UI.refreshRecordingUi();
    Scrubber.init(document.getElementById("scrubberCanvas"));
    UI.refreshAllUiText(analysisFrame);
    resizeCanvasToDisplaySize();
    window.addEventListener("resize", resizeCanvasToDisplaySize);
    requestAnimationFrame(onAnimationFrame);
  }
  main();
})();
